commands:
truncate -s 0 '/etc/nginx//blacklisted-sessions.map'; [ -f "/run/nginx.pid" ] && nginx -qt; if [ $? -eq 0 ]; then
nginx -s reload; if [ $? -ne 0 ]; then echo 'reload failed.'; fi;
fi;

truncate -s 0 '/etc/nginx//blacklisted-sessions.map'; [ -f "/run/nginx.pid" ] && nginx -qt; if [ $? -eq 0 ]; then
nginx -s reload; if [ $? -ne 0 ]; then echo 'reload failed.'; fi;
fi;

printf '\%s 1;\n' "<fid>" >> '/etc/nginx//blacklisted-sessions.map'; [ -f "/run/nginx.pid" ] && nginx -qt; if [ $? -eq 0 ]; then
nginx -s reload; if [ $? -ne 0 ]; then echo 'reload failed.'; fi;
fi;

id=$(printf '\%s 1;\n' "<fid>" | sed -e 's/[]\/$*.^|[]/\\&/g'); sed -i "/^$id$/d" /etc/nginx//blacklisted-sessions.map; [ -f "/run/nginx.pid" ] && nginx -qt; if [ $? -eq 0 ]; then
nginx -s reload; if [ $? -ne 0 ]; then echo 'reload failed.'; fi;
fi;
